package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.*;import dev.redstoneengineering.physics.InformationRuntime;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.RandomSource;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.IntegerProperty;import net.minecraft.world.phys.BlockHitResult;
/** Aligned, channel-selective free-space optical receiver. Beam must enter the back face. */
public class FreeSpaceOpticalReceiverBlock extends PassiveDirectionalSignalBlock{public static final IntegerProperty CHANNEL=IntegerProperty.create("channel",0,3);public FreeSpaceOpticalReceiverBlock(Properties p){super(p);registerDefaultState(defaultBlockState().setValue(CHANNEL,0));}@Override public MapCodec<FreeSpaceOpticalReceiverBlock> codec(){return RedstoneEngineering.FREE_SPACE_OPTICAL_RECEIVER_CODEC.value();}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){super.createBlockStateDefinition(b);b.add(CHANNEL);}@Override protected int computeOutput(Level l,BlockPos p,BlockState s){return InformationRuntime.valid(l,"free_optical",p)&&InformationRuntime.quality(l,"free_optical",p)>0&&InformationRuntime.aux(l,"free_optical",p)==s.getValue(CHANNEL)?Math.min(15,InformationRuntime.value(l,"free_optical",p)):0;}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl)sl.scheduleTick(p,this,5);}@Override protected void tick(BlockState s,ServerLevel l,BlockPos p,RandomSource r){int q=InformationRuntime.quality(l,"free_optical",p);if(q>0)InformationRuntime.write(l,"free_optical",p,InformationRuntime.value(l,"free_optical",p),InformationRuntime.aux(l,"free_optical",p),q>20,q-20);updateOutput(l,p,s,outputValue(l,p,s));l.scheduleTick(p,this,5);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide){int c=(s.getValue(CHANNEL)+1)%4;BlockState ns=s.setValue(CHANNEL,c);l.setBlock(p,ns,Block.UPDATE_CLIENTS);pl.displayClientMessage(Component.literal("Free-space optical RX ch="+c+" power="+InformationRuntime.value(l,"free_optical",p)+" quality="+InformationRuntime.quality(l,"free_optical",p)+"% | alignment required"),true);}return InteractionResult.sidedSuccess(l.isClientSide);}}
